cat > /app/output/styles.css <<'EOF'
:root {
  --blue: #3861fb;
  --blue-strong: #2147d8;
  --navy: #0d1421;
  --muted: #58667e;
  --subtle: #808a9d;
  --line: #eff2f5;
  --panel: #ffffff;
  --bg: #f8fafc;
  --green: #16c784;
  --red: #ea3943;
  --amber: #f59e0b;
  --shadow: 0 16px 45px rgba(13, 20, 33, 0.08);
  --mono: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--navy);
  font-family: var(--mono);
  font-feature-settings: "tnum" 1, "lnum" 1;
  -webkit-font-smoothing: antialiased;
}

button, input, select { font: inherit; }
button { cursor: pointer; }
a { color: inherit; text-decoration: none; }

.site-header {
  background: rgba(255,255,255,0.96);
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  z-index: 30;
  backdrop-filter: blur(14px);
}

.utility-bar,
.main-nav,
main,
.site-footer {
  width: min(1520px, calc(100% - 32px));
  margin: 0 auto;
}

.utility-bar {
  min-height: 36px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  color: var(--muted);
  font-size: 12px;
  border-bottom: 1px solid var(--line);
}

.metric-strip {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.metric-strip strong { color: var(--navy); font-weight: 700; }
em { font-style: normal; }
.positive { color: var(--green) !important; }
.negative { color: var(--red) !important; }

.utility-actions,
.nav-actions,
.toolbar-actions,
.tabs-row,
.pagination,
.page-buttons {
  display: flex;
  align-items: center;
  gap: 10px;
}

.main-nav {
  min-height: 68px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 22px;
}

.brand,
.footer-brand strong {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  letter-spacing: -0.03em;
  font-size: 20px;
}

.brand-mark {
  width: 34px;
  height: 34px;
  display: inline-grid;
  place-items: center;
  color: white;
  background: linear-gradient(135deg, var(--blue), #6a8bff);
  border-radius: 11px;
  box-shadow: 0 10px 24px rgba(56,97,251,0.28);
}

.nav-links {
  display: flex;
  gap: 24px;
  color: var(--navy);
  font-size: 14px;
  font-weight: 650;
  flex: 1;
}

.nav-links a:hover { color: var(--blue); }

.search-box {
  height: 40px;
  min-width: 275px;
  display: flex;
  align-items: center;
  gap: 8px;
  background: #f5f7fb;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 0 12px;
  color: var(--subtle);
}
.search-box input { border: 0; outline: 0; background: transparent; width: 100%; color: var(--navy); }

.primary-button,
.ghost-button,
.control-button,
.carousel-button,
.page,
.link-button {
  border: 0;
  border-radius: 10px;
  font-weight: 700;
  transition: transform .18s ease, background .18s ease, border-color .18s ease, color .18s ease;
}
.primary-button { background: var(--blue); color: #fff; padding: 10px 16px; box-shadow: 0 8px 22px rgba(56,97,251,.22); }
.primary-button:hover { background: var(--blue-strong); transform: translateY(-1px); }
.ghost-button { background: #f5f7fb; color: var(--navy); padding: 10px 14px; }
.ghost-button.small { padding: 6px 9px; font-size: 12px; }

main { padding: 26px 0 42px; }
.hero-grid {
  display: grid;
  grid-template-columns: minmax(340px, 0.9fr) 1.55fr;
  gap: 24px;
  align-items: stretch;
}
.title-block,
.dashboard-panel,
.market-summary,
.info-grid article,
.promo-card,
.ai-alerts {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 18px;
  box-shadow: 0 1px 2px rgba(13,20,33,.03);
}
.title-block { padding: 28px; }
.eyebrow { margin: 0 0 10px; color: var(--blue); font-weight: 800; font-size: 12px; letter-spacing: .08em; text-transform: uppercase; }
h1 { margin: 0; font-size: clamp(28px, 3vw, 46px); line-height: 1.05; letter-spacing: -0.055em; }
.title-block > p:last-child { margin: 16px 0 0; color: var(--muted); line-height: 1.65; max-width: 680px; }

.stat-cards { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; }
.stat-card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 22px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 160px;
}
.stat-card.accent { background: linear-gradient(135deg, #0d1421, #16233a); color: #fff; border-color: transparent; box-shadow: var(--shadow); }
.stat-card span { color: var(--subtle); font-size: 13px; font-weight: 700; }
.stat-card strong { font-size: clamp(24px, 2.3vw, 34px); letter-spacing: -0.045em; margin-top: 18px; }
.stat-card em { color: var(--muted); font-size: 13px; font-weight: 750; }

.promo-shell { display: grid; grid-template-columns: 42px 1fr 42px; gap: 12px; align-items: center; margin: 22px 0; }
.promo-card {
  min-height: 112px;
  padding: 20px 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  overflow: hidden;
  position: relative;
}
.promo-card::after {
  content: "";
  position: absolute;
  right: -70px;
  top: -90px;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(56,97,251,.16), transparent 65%);
  pointer-events: none;
}
.promo-card h2 { margin: 8px 0 5px; font-size: 22px; letter-spacing: -0.035em; }
.promo-card p { margin: 0; color: var(--muted); }
.carousel-button { width: 42px; height: 42px; background: #fff; border: 1px solid var(--line); color: var(--navy); font-size: 25px; }

.pill { display: inline-flex; align-items: center; height: 23px; padding: 0 9px; border-radius: 999px; font-size: 11px; font-weight: 800; }
.pill.blue { background: rgba(56,97,251,.1); color: var(--blue); }
.pill.navy { background: rgba(13,20,33,.08); color: var(--navy); }

.ai-alerts { padding: 16px 18px; display: flex; gap: 16px; align-items: center; margin-bottom: 22px; }
.alert-topic { display: flex; gap: 10px; align-items: center; flex: 0 0 auto; }
.spark { width: 30px; height: 30px; display: grid; place-items: center; background: rgba(56,97,251,.1); color: var(--blue); border-radius: 50%; }
.quick-asks { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 2px; }
.quick-asks button { flex: 0 0 auto; border: 1px solid var(--line); background: #f8fafc; color: var(--muted); border-radius: 999px; padding: 8px 11px; font-size: 12px; font-weight: 700; }
.quick-asks button:hover { color: var(--blue); border-color: rgba(56,97,251,.35); }

.dashboard-panel { padding: 0; overflow: hidden; }
.tabs-row { padding: 14px 18px; justify-content: space-between; overflow-x: auto; }
.with-border { border-bottom: 1px solid var(--line); }
.tab-group { display: flex; gap: 8px; min-width: max-content; }
.tab {
  border: 1px solid transparent;
  background: transparent;
  color: var(--muted);
  padding: 9px 12px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 800;
}
.tab:hover { color: var(--blue); background: rgba(56,97,251,.06); }
.tab.active { color: var(--blue); background: rgba(56,97,251,.1); border-color: rgba(56,97,251,.18); }
.network-tabs .tab.active { color: #0f8d5b; background: rgba(22,199,132,.1); border-color: rgba(22,199,132,.22); }

.index-tracker {
  margin: 0 18px 14px;
  padding: 14px 16px;
  border: 1px solid var(--line);
  border-radius: 14px;
  display: grid;
  grid-template-columns: minmax(260px, 1fr) repeat(4, 150px);
  gap: 16px;
  align-items: center;
  background: linear-gradient(180deg, #fff, #fbfcff);
}
.index-tracker > div:first-child { display: flex; align-items: center; gap: 10px; }
.index-tracker small { color: var(--subtle); font-weight: 800; }
.index-metric { text-align: right; }
.index-metric span { display: block; color: var(--subtle); font-size: 11px; font-weight: 800; text-transform: uppercase; }
.index-metric strong { font-size: 15px; }

.table-toolbar {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: center;
  padding: 16px 18px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.table-toolbar h2 { margin: 0 0 5px; font-size: 22px; letter-spacing: -0.035em; }
.table-toolbar p { margin: 0; color: var(--muted); font-size: 13px; }
.control-button { background: #fff; color: var(--navy); border: 1px solid var(--line); padding: 9px 12px; font-size: 13px; }
.control-button:hover, .control-button.active-sort { border-color: rgba(56,97,251,.35); color: var(--blue); background: rgba(56,97,251,.06); }

.filter-panel,
.columns-panel {
  margin: 14px 18px 0;
  padding: 14px;
  border: 1px solid rgba(56,97,251,.18);
  border-radius: 14px;
  background: #fbfcff;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  align-items: center;
}
.filter-panel[hidden], .columns-panel[hidden] { display: none; }
.filter-panel label, .columns-panel label { color: var(--muted); font-size: 12px; font-weight: 800; display: grid; gap: 6px; }
.filter-panel input, .filter-panel select { height: 38px; border: 1px solid var(--line); border-radius: 10px; padding: 0 10px; background: #fff; color: var(--navy); min-width: 180px; }
.columns-panel { gap: 18px; }
.columns-panel label { display: inline-flex; align-items: center; gap: 7px; }

.table-wrap { overflow: auto; max-height: 980px; }
.crypto-table { width: 100%; min-width: 1220px; border-collapse: separate; border-spacing: 0; font-size: 13px; }
.crypto-table thead th {
  position: sticky;
  top: 0;
  z-index: 3;
  background: #fff;
  color: var(--subtle);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: .04em;
  padding: 11px 12px;
  border-bottom: 1px solid var(--line);
  text-align: left;
  white-space: nowrap;
}
.crypto-table tbody td {
  padding: 12px;
  border-bottom: 1px solid var(--line);
  background: #fff;
  white-space: nowrap;
  vertical-align: middle;
}
.crypto-table tbody tr:hover td { background: #fbfcff; }
.rank-col { width: 52px; color: var(--subtle); text-align: right !important; }
.name-col { min-width: 245px; position: sticky; left: 0; z-index: 2; background: inherit !important; }
.num { text-align: right !important; font-variant-numeric: tabular-nums; }
.spark-col { text-align: center !important; min-width: 150px; }
.coin-name { display: flex; align-items: center; gap: 10px; }
.logo {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #fff;
  font-size: 11px;
  font-weight: 900;
  background: var(--coin-color, var(--blue));
  box-shadow: inset 0 -8px 18px rgba(0,0,0,.13);
}
.coin-name strong { font-size: 14px; }
.coin-name small { color: var(--subtle); font-weight: 800; margin-left: 5px; }
.star { color: #c7ceda; font-size: 17px; }
.network-badge { display: inline-block; margin-left: 6px; color: var(--subtle); background: #f5f7fb; border-radius: 999px; padding: 2px 6px; font-size: 10px; font-weight: 800; }
.sparkline svg { width: 128px; height: 38px; overflow: visible; }
.sparkline path.line { fill: none; stroke: var(--green); stroke-width: 2.3; stroke-linecap: round; stroke-linejoin: round; }
.sparkline path.area { fill: rgba(22,199,132,.10); }
.sparkline.negative path.line { stroke: var(--red); }
.sparkline.negative path.area { fill: rgba(234,57,67,.08); }

.pagination { padding: 16px 18px; justify-content: space-between; color: var(--muted); font-size: 13px; border-top: 1px solid var(--line); }
.page { min-width: 36px; height: 36px; background: #fff; border: 1px solid var(--line); color: var(--muted); }
.page.active { background: var(--blue); color: #fff; border-color: var(--blue); }

.market-summary { padding: 24px; margin-top: 22px; line-height: 1.72; }
.market-summary h2 { margin: 0 0 10px; font-size: 26px; letter-spacing: -0.04em; }
.market-summary p { color: var(--muted); margin: 8px 0; max-width: 1120px; }
.market-summary strong { color: var(--navy); }
.link-button { background: transparent; color: var(--blue); padding: 8px 0; margin-top: 4px; }

.info-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 14px; margin-top: 22px; background: transparent; border: 0; box-shadow: none; }
.info-grid article { padding: 18px; }
.info-grid h3 { margin: 0 0 9px; font-size: 16px; letter-spacing: -0.02em; }
.info-grid p { margin: 0; color: var(--muted); line-height: 1.55; font-size: 13px; }

.site-footer { padding: 36px 0 30px; border-top: 1px solid var(--line); display: grid; grid-template-columns: 320px 1fr; gap: 42px; color: var(--muted); }
.footer-brand p { line-height: 1.55; }
.footer-cols { display: grid; grid-template-columns: repeat(4, 1fr); gap: 26px; }
.footer-cols h4 { margin: 0 0 10px; color: var(--navy); }
.footer-cols a { display: block; margin: 7px 0; font-size: 13px; }
.copyright { grid-column: 1 / -1; margin: 0; font-size: 12px; }

body.hide-price .col-price,
body.hide-h1 .col-h1,
body.hide-h24 .col-h24,
body.hide-d7 .col-d7,
body.hide-marketCap .col-marketCap,
body.hide-volume .col-volume,
body.hide-supply .col-supply,
body.hide-sparkline .col-sparkline { display: none; }

@media (max-width: 1180px) {
  .hero-grid { grid-template-columns: 1fr; }
  .stat-cards { grid-template-columns: repeat(2, 1fr); }
  .nav-links { display: none; }
  .index-tracker { grid-template-columns: repeat(5, minmax(140px, 1fr)); overflow-x: auto; }
  .info-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 760px) {
  .utility-bar { display: none; }
  .main-nav { flex-wrap: wrap; padding: 12px 0; }
  .nav-actions { width: 100%; flex-wrap: wrap; }
  .search-box { min-width: 100%; }
  .hero-grid { gap: 14px; }
  .stat-cards { grid-template-columns: 1fr; }
  .promo-shell { grid-template-columns: 1fr; }
  .carousel-button { display: none; }
  .promo-card, .ai-alerts, .table-toolbar, .pagination { align-items: flex-start; flex-direction: column; }
  .toolbar-actions { flex-wrap: wrap; }
  .index-tracker { display: flex; overflow-x: auto; }
  .index-tracker > div { min-width: 140px; }
  .info-grid { grid-template-columns: 1fr; }
  .site-footer { grid-template-columns: 1fr; }
  .footer-cols { grid-template-columns: repeat(2, 1fr); }
}
EOF

